"""Plots and the auto-generated results report.

Everything in results/ is regenerated by ``python -m tsbench``, so the numbers
in RESULTS.md can never drift away from the code that produced them.
"""
from __future__ import annotations

import json
import platform
import sys
from datetime import datetime, timezone
from importlib import metadata
from pathlib import Path

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt  # noqa: E402
import numpy as np  # noqa: E402
import pandas as pd  # noqa: E402

from .data import Dataset  # noqa: E402

# Colour encodes model *family*, so the same family has the same colour on every chart.
FAMILY_COLORS = {
    "baseline": "#8a8985",  # neutral gray - the reference everyone must beat
    "statistical": "#2a78d6",  # blue
    "ml": "#eb6834",  # orange
    "foundation": "#1baf7a",  # aqua
}
FAMILY_LABELS = {"baseline": "baseline", "statistical": "statistical",
                 "ml": "machine learning", "foundation": "foundation model"}
INK, MUTED, GRID = "#0b0b0b", "#52514e", "#e4e3df"

plt.rcParams.update({
    "font.size": 9, "axes.edgecolor": MUTED, "axes.labelcolor": INK,
    "axes.titlesize": 10, "axes.titleweight": "bold", "axes.spines.top": False,
    "axes.spines.right": False, "xtick.color": MUTED, "ytick.color": MUTED,
    "axes.grid": True, "grid.color": GRID, "grid.linewidth": 0.8,
    "legend.frameon": False, "figure.dpi": 130, "savefig.bbox": "tight",
})


def _figure_legend(fig, summary: pd.DataFrame) -> None:
    """One family legend centred under all panels, so it never covers data."""
    families = [f for f in FAMILY_COLORS if f in set(summary["family"])]
    handles = [plt.Rectangle((0, 0), 1, 1, color=FAMILY_COLORS[f]) for f in families]
    fig.legend(handles, [FAMILY_LABELS[f] for f in families], loc="lower center",
               ncol=len(families), fontsize=8, bbox_to_anchor=(0.5, -0.06))


def _place_labels(ax, xs, ys, labels, min_dy=0.055):
    """Direct labels with a simple greedy de-overlap in axes-fraction units."""
    x0, x1 = ax.get_xlim()
    y0, y1 = ax.get_ylim()
    fx = (np.log10(xs) - np.log10(x0)) / (np.log10(x1) - np.log10(x0))
    fy = (np.asarray(ys) - y0) / (y1 - y0)
    placed: list[tuple[float, float]] = []
    for i in np.argsort(fy):
        ty = fy[i]
        while any(abs(fx[i] - px) < 0.18 and abs(ty - py) < min_dy for px, py in placed):
            ty += min_dy
        placed.append((fx[i], ty))
        ax.annotate(labels[i], (xs[i], ys[i]), xytext=(fx[i] + 0.02, ty + 0.01),
                    textcoords="axes fraction", fontsize=7, color=INK, va="bottom",
                    arrowprops=dict(arrowstyle="-", color=GRID, lw=0.8)
                    if abs(ty - fy[i]) > 1e-9 else None)


# --------------------------------------------------------------------------- plots
def plot_mase_comparison(summary: pd.DataFrame, folds: pd.DataFrame, path: Path) -> None:
    """Small multiples: mean MASE per model (bar), 95% CI (whisker), each fold (dot)."""
    datasets = list(summary["dataset"].unique())
    fig, axes = plt.subplots(1, len(datasets), figsize=(4.2 * len(datasets), 3.6),
                             squeeze=False)
    rng = np.random.default_rng(0)
    for ax, ds in zip(axes[0], datasets):
        s = summary[summary["dataset"] == ds].iloc[::-1]  # best at the top
        ypos = np.arange(len(s))
        colors = [FAMILY_COLORS[f] for f in s["family"]]
        ax.barh(ypos, s["mase"], color=colors, height=0.62, alpha=0.9, zorder=2)
        ax.errorbar(s["mase"], ypos, xerr=[s["mase"] - s["ci_low"], s["ci_high"] - s["mase"]],
                    fmt="none", ecolor=INK, elinewidth=1, capsize=2.5, zorder=4)
        f = folds[(folds["dataset"] == ds) & folds["error"].isna()]
        for y, m in zip(ypos, s["model"]):
            v = f.loc[f["model"] == m, "mase"].to_numpy()
            ax.scatter(v, y + rng.uniform(-0.18, 0.18, len(v)), s=7, color=INK,
                       alpha=0.35, linewidths=0, zorder=3)
        ax.axvline(1.0, color=MUTED, ls="--", lw=1, zorder=1)
        ax.set_yticks(ypos, s["model"])
        ax.grid(axis="y", visible=False)
        ax.set_title(ds, loc="left")
        ax.set_xlabel("MASE (lower is better)")
        ax.set_xlim(left=0)
    _figure_legend(fig, summary)
    fig.suptitle("Mean MASE across rolling-origin folds  ·  whisker = 95% bootstrap CI  ·  "
                 "dots = individual folds  ·  dashed = MASE 1", x=0.01, ha="left",
                 fontsize=9, color=MUTED)
    fig.tight_layout()
    fig.savefig(path)
    plt.close(fig)


def plot_final_fold(ds: Dataset, forecasts: pd.DataFrame, summary: pd.DataFrame,
                    path: Path, alpha: float | None) -> None:
    """One panel per model: history, actual, forecast and its conformal interval."""
    fc = forecasts[forecasts["dataset"] == ds.name]
    last = fc["fold"].max()
    fc = fc[fc["fold"] == last]
    models = list(summary.loc[summary["dataset"] == ds.name, "model"])  # best first
    families = dict(zip(summary["model"], summary["family"]))
    origin = int(fc["origin"].iloc[0])
    y = ds.values
    ctx = 4 * ds.horizon
    hx = np.arange(-ctx, 0)
    fx = np.arange(ds.horizon)
    ncols = min(4, len(models))
    nrows = int(np.ceil(len(models) / ncols))
    fig, axes = plt.subplots(nrows, ncols, figsize=(3.3 * ncols, 2.5 * nrows),
                             sharex=True, sharey=True, squeeze=False)
    for ax in axes.flat[len(models):]:
        ax.set_visible(False)
    for ax, m in zip(axes.flat, models):
        g = fc[fc["model"] == m].sort_values("step")
        c = FAMILY_COLORS[families[m]]
        ax.plot(hx, y[origin - ctx:origin], color=MUTED, lw=1.2)
        ax.plot(fx, g["actual"], color=INK, lw=2)
        if alpha is not None and g["lo"].notna().all():
            ax.fill_between(fx, g["lo"], g["hi"], color=c, alpha=0.2, lw=0)
        ax.plot(fx, g["pred"], color=c, lw=2)
        ax.axvline(-0.5, color=GRID, lw=1)
        mase = summary.loc[(summary["dataset"] == ds.name) & (summary["model"] == m), "mase"]
        ax.set_title(f"{m}   (mean MASE {mase.iloc[0]:.2f})", loc="left", fontsize=9)
    for ax in axes[-1]:
        ax.set_xlabel("steps from forecast origin")
    band = f" · shaded = {round(100 * (1 - alpha))}% conformal interval" if alpha else ""
    fig.suptitle(f"{ds.name}: final fold  ·  gray = history · black = actual · "
                 f"colour = forecast{band}", x=0.01, ha="left", fontsize=9, color=MUTED)
    fig.tight_layout()
    fig.savefig(path)
    plt.close(fig)


def plot_accuracy_vs_cost(summary: pd.DataFrame, path: Path) -> None:
    """Is the extra compute worth it? Mean fit time per forecast vs mean MASE."""
    if "fit_seconds" not in summary:
        return
    datasets = list(summary["dataset"].unique())
    fig, axes = plt.subplots(1, len(datasets), figsize=(4.2 * len(datasets), 3.3),
                             squeeze=False)
    for ax, ds in zip(axes[0], datasets):
        s = summary[summary["dataset"] == ds]
        ax.scatter(s["fit_seconds"].clip(lower=1e-4), s["mase"], s=48,
                   c=[FAMILY_COLORS[f] for f in s["family"]], edgecolors="white",
                   linewidths=1.5, zorder=3)
        ax.set_xscale("log")
        xs = s["fit_seconds"].clip(lower=1e-4).to_numpy()
        ax.set_xlim(xs.min() / 3, xs.max() * 8)
        lo, hi = s["mase"].min(), s["mase"].max()
        ax.set_ylim(lo - 0.08 * (hi - lo), hi + 0.25 * (hi - lo))
        _place_labels(ax, xs, s["mase"].to_numpy(), list(s["model"]))
        ax.set_title(ds, loc="left")
        ax.set_xlabel("median seconds per fit + forecast (log)")
        ax.set_ylabel("mean MASE (lower is better)")
    _figure_legend(fig, summary)
    fig.tight_layout()
    fig.savefig(path)
    plt.close(fig)


def _spread(values: list[float], gap: float) -> list[float]:
    """Move label positions apart by at least ``gap`` while staying centred on the data."""
    order = np.argsort(values)
    pos = np.asarray(values, dtype=float)[order]
    for _ in range(200):  # simple relaxation: push overlapping neighbours apart symmetrically
        moved = False
        for i in range(1, len(pos)):
            d = pos[i] - pos[i - 1]
            if d < gap:
                shift = (gap - d) / 2
                pos[i - 1] -= shift
                pos[i] += shift
                moved = True
        if not moved:
            break
    out = np.empty_like(pos)
    out[order] = pos
    return list(out)


def plot_error_by_horizon(forecasts: pd.DataFrame, summary: pd.DataFrame, path: Path) -> None:
    """How fast does each model's error grow with the forecast horizon?

    Scaled absolute error (|actual - pred| / naive scale, i.e. MASE per step),
    averaged over folds. Shows the naive baseline, the best statistical and ML
    model per dataset, and the foundation models; everything else in light gray.
    """
    fc = forecasts.dropna(subset=["pred"]).assign(
        err=lambda d: (d["actual"] - d["pred"]).abs() / d["scale"])
    datasets = list(summary["dataset"].unique())
    fig, axes = plt.subplots(1, len(datasets), figsize=(4.2 * len(datasets), 3.3),
                             squeeze=False)
    for ax, ds in zip(axes[0], datasets):
        s = summary[summary["dataset"] == ds]
        curves = fc[fc["dataset"] == ds].groupby(["model", "step"])["err"].mean().unstack(0)
        fam = dict(zip(s["model"], s["family"]))
        highlight = {"Naive"}
        for f in ("statistical", "ml"):
            best = s[s["family"] == f]
            if len(best):
                highlight.add(best.iloc[0]["model"])  # summary is sorted best first
        highlight |= {m for m in curves if fam.get(m) == "foundation"}
        for m in curves:
            if m not in highlight:
                ax.plot(curves.index, curves[m], color=GRID, lw=1, zorder=1)
        labels = []
        for m in curves:
            if m in highlight:
                ls = "--" if m == "TTM" else "-"
                ax.plot(curves.index, curves[m], color=FAMILY_COLORS[fam[m]], lw=2, ls=ls,
                        zorder=3)
                labels.append((curves[m].iloc[-1], m))
        # direct labels at the line ends, nudged apart vertically
        y0, y1 = ax.get_ylim()
        for v, m in zip(_spread([v for v, _ in labels], 0.065 * (y1 - y0)),
                        [m for _, m in labels]):
            ax.annotate(m, (curves.index[-1], v), xytext=(5, 0), textcoords="offset points",
                        fontsize=7, color=INK, va="center", annotation_clip=False)
        steps = list(curves.index)
        ax.set_xticks(steps if len(steps) <= 6 else [x for x in steps if x == 1 or x % 3 == 0])
        ax.set_xlim(steps[0] - 0.3, steps[-1] + 0.3)
        ax.set_title(ds, loc="left")
        ax.set_xlabel("forecast step")
        ax.set_ylabel("scaled abs. error (lower is better)")
    fig.suptitle("Error growth with horizon  ·  gray = other models  ·  dashed = TTM zero-shot",
                 x=0.01, ha="left", fontsize=9, color=MUTED)
    fig.tight_layout(w_pad=4)
    fig.savefig(path)
    plt.close(fig)


# --------------------------------------------------------------------------- markdown
def _fmt(v, nd=2):
    return "–" if v is None or (isinstance(v, float) and not np.isfinite(v)) else f"{v:.{nd}f}"


def _p(v):
    if not np.isfinite(v):
        return "best"
    return "<0.001" if v < 0.001 else f"{v:.3f}"


def results_markdown(summary: pd.DataFrame, datasets: list[Dataset], folds: pd.DataFrame,
                     alpha: float | None, meta: dict) -> str:
    lines = ["# Benchmark results", "",
             f"_Generated by `python -m tsbench` on {meta['timestamp']} "
             f"in {meta['runtime_seconds']:.0f}s. Do not edit by hand._", "",
             "* **MASE**: mean over folds; 95% bootstrap CI in brackets. Lower is better.",
             "* **rank**: mean rank across folds (1 = best in every fold).",
             "* **p vs best**: paired Wilcoxon signed-rank test against the best model, "
             "Holm-corrected. **Bold** = significantly worse at the 5% level.", ""]
    if alpha is not None:
        lvl = round(100 * (1 - alpha))
        lines += [f"* **cov{lvl}**: empirical coverage of the {lvl}% conformal interval "
                  f"(target {lvl / 100:.2f}). **MSIS**: scaled interval score, "
                  "lower is better.", ""]
    for ds in datasets:
        s = summary[summary["dataset"] == ds.name]
        if s.empty:
            continue
        lines += [f"## {ds.name}", "", f"{ds.description}. {len(ds)} observations, "
                  f"horizon {ds.horizon}, {ds.n_folds} folds.", ""]
        head = "| Model | MASE (95% CI) | rank | p vs best | MAE |"
        sep = "|---|---|---|---|---|"
        if alpha is not None:
            head += f" cov{round(100 * (1 - alpha))} | MSIS |"
            sep += "---|---|"
        head += " sec/fit |"
        sep += "---|"
        lines += [head, sep]
        for _, r in s.iterrows():
            p = _p(r["p_vs_best"])
            if r["significantly_worse"]:
                p = f"**{p}**"
            cells = [f"{'**' + r['model'] + '**' if r['is_best'] else r['model']}",
                     f"{_fmt(r['mase'])} ({_fmt(r['ci_low'])}–{_fmt(r['ci_high'])})",
                     _fmt(r["mean_rank"], 1), p, _fmt(r["mae"], 3 if r["mae"] < 1 else 1)]
            if alpha is not None:
                cells += [_fmt(r.get("coverage", np.nan)), _fmt(r.get("msis", np.nan))]
            cells.append(_fmt(r.get("fit_seconds", np.nan), 3))
            lines.append("| " + " | ".join(cells) + " |")
        lines.append("")
    errs = folds[folds["error"].notna()]
    if len(errs):
        lines += ["## Failed fits", "", "| dataset | model | fold | error |", "|---|---|---|---|"]
        lines += [f"| {r.dataset} | {r.model} | {r.fold} | {r.error} |" for r in errs.itertuples()]
        lines.append("")
    lines += ["## Figures", "", "![MASE comparison](mase_comparison.png)", ""]
    lines += [f"![{d.name}](forecasts_{d.name}.png)" for d in datasets]
    lines += ["", "![Error by horizon](error_by_horizon.png)",
              "", "![Accuracy vs cost](accuracy_vs_cost.png)", ""]
    return "\n".join(lines)


def run_metadata(config: dict, runtime: float) -> dict:
    pkgs = ["numpy", "pandas", "scikit-learn", "statsmodels", "scipy", "torch", "granite-tsfm"]
    versions = {}
    for p in pkgs:
        try:
            versions[p] = metadata.version(p)
        except metadata.PackageNotFoundError:
            pass
    return dict(timestamp=datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M UTC"),
                runtime_seconds=runtime, python=sys.version.split()[0],
                platform=platform.platform(), packages=versions, config=config)


def write_metadata(meta: dict, path: Path) -> None:
    path.write_text(json.dumps(meta, indent=2, default=str), encoding="utf-8")
